            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < panels.length; i++) {
                var p = document.getElementById(panels[i]);
                if (p) p.style.display = (i === period - 1) ? 'block' : 'none';
            }

            if (!briefEl) return;

            if (period === 1) {
                briefEl.innerHTML = '<strong>' + t('r1_heading') + '</strong><br>' + t('r1_briefing');
            } else if (period === 2) {
                briefEl.innerHTML = '<strong>' + t('r2_heading') + '</strong><br>' + t('r2_briefing');
