        _setupBudgetListeners() {
            var ids = ['ergonomicsInput', 'healthInput', 'transportInput', 'daycareInput', 'careerInput', 'climateInput'];
            var updateTotal = function() {
                var total = 0;
                for (var i = 0; i < ids.length; i++) {
                    var el = document.getElementById(ids[i]);
                    if (el) total += parseFloat(el.value) || 0;
                }
                var display = document.getElementById('budgetTotalDisplay');
                var summary = document.getElementById('budgetSummary');
                if (display) display.textContent = 'BRL ' + total.toLocaleString() + 'K';
                if (summary) {
                    if (total > 8000) { summary.classList.add('over-budget'); }
                    else { summary.classList.remove('over-budget'); }
                }
            };
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el) {
                    el.removeEventListener('input', updateTotal);
                    el.addEventListener('input', updateTotal);
                }
            }
            updateTotal();
        }
